const item = $input.item.json;
const body = item.body || item;
const title = (body.title || 'Untitled Post').trim();
const content = (body.content || body.markdown || body.text || '').trim();
const author = (body.author || 'Author').trim();

if (!content || content.length < 150) {
  throw new Error('Content too short to repurpose. Provide at least 150 characters.');
}

return {
  json: {
    contentId: 'art_' + Date.now().toString(36),
    title,
    content,
    author,
    submittedAt: new Date().toISOString()
  }
};

const initial = $('Validate & Clean Text').first().json;
const threadRes = $('Generate X Thread').first().json;
const carouselRes = $('Generate LinkedIn Carousel').first().json;
const newsletterRes = $('Generate Newsletter').first().json;

const threadText = (threadRes.choices && threadRes.choices[0] && threadRes.choices[0].message) ? threadRes.choices[0].message.content : 'Thread generation error';
const carouselText = (carouselRes.choices && carouselRes.choices[0] && carouselRes.choices[0].message) ? carouselRes.choices[0].message.content : 'Carousel generation error';
const newsletterText = (newsletterRes.choices && newsletterRes.choices[0] && newsletterRes.choices[0].message) ? newsletterRes.choices[0].message.content : 'Newsletter generation error';

return [{
  json: {
    contentId: initial.contentId,
    title: initial.title,
    author: initial.author,
    status: 'NEEDS_HUMAN_REVIEW',
    assets: {
      twitterThread: threadText,
      linkedInCarousel: carouselText,
      newsletter: newsletterText
    }
  }
}];
